public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        throw new IllegalArgumentException("String cannot be null");
    }

    int length = str.length();
    for (int i = 0; i < length; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            lb.write((byte) c);
        } else if (c < 0x800) {
            lb.write((byte) (0xc0 | (c >> 6)));
            lb.write((byte) (0x80 | (c & 0x3f)));
        } else if (c < 0x10000) {
            lb.write((byte) (0xe0 | (c >> 12)));
            lb.write((byte) (0x80 | ((c >> 6) & 0x3f)));
            lb.write((byte) (0x80 | (c & 0x3f)));
        } else if (c < 0x200000) {
            lb.write((byte) (0xf0 | (c >> 18)));
            lb.write((byte) (0x80 | ((c >> 12) & 0x3f)));
            lb.write((byte) (0x80 | ((c >> 6) & 0x3f)));
            lb.write((byte) (0x80 | (c & 0x3f)));
        } else {
            throw new IllegalArgumentException("String contains characters outside the UTF-8 range");
        }
    }

    return lb;
}

