private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }
    if (node.next == null) {
        // If the node is the last node, set the previous node's next to null
        if (node.prev != null) {
            node.prev.next = null;
        }
        return true;
    } else {
        // If the node is not the last node, update the next node's previous to the previous node
        node.next.prev = node.prev;
        // Update the previous node's next to the next node
        node.prev.next = node.next;
        return true;
    }
}

