public class SuffixSumCalculator {
    /**
     * Computes a suffix sum of the given list of integers. Returns a pair of lists containing the computed suffix sums
     * and the sum of all elements in the list.
     * 
     * @param bounds List of integers.
     * @return A pair of lists containing the computed suffix sums and the sum of all elements.
     */
    private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
        List<Integer> suffixSums = new ArrayList<>();
        long totalSum = 0;

        // Calculate suffix sums
        for (int i = bounds.size() - 1; i >= 0; i--) {
            totalSum += bounds.get(i);
            suffixSums.add(totalSum);
        }

        // Reverse the list of suffix sums to get the correct order
        Collections.reverse(suffixSums);

        return new Pair<>(suffixSums, totalSum);
    }

    // Helper class to hold a pair of values
    private static class Pair<T1, T2> {
        private T1 first;
        private T2 second;

        public Pair(T1 first, T2 second) {
            this.first = first;
            this.second = second;
        }

        public T1 getFirst() {
            return first;
        }

        public T2 getSecond() {
            return second;
        }
    }
}

public static final <V> void reverse(V[] arr, int from, int to) {
    while (from < to) {
        V temp = arr[from];
        arr[from] = arr[to];
        arr[to] = temp;
        from++;
        to--;
    }
}

