private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    // Check if the number of vertices in the subgraph is equal to the number of vertices in the original graph
    if (vertices.size() != graph.vertexSet().size()) {
        return false;
    }

    // Iterate through each vertex in the subgraph
    for (V vertex : vertices) {
        // Check if the vertex is connected to all other vertices in the subgraph
        for (V neighbor : vertices) {
            if (!graph.containsEdge(vertex, neighbor)) {
                return false;
            }
        }
    }

    return true;
}

