public static String applyRelativePath(String path, String relativePath) {
    // Split the path and relative path into components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Initialize the result path
    StringBuilder resultPath = new StringBuilder();

    // Iterate through the relative path components
    for (String component : relativePathComponents) {
        // If the component is ".", skip it
        if (component.equals(".")) {
            continue;
        }
        // If the component is "..", go up one directory
        else if (component.equals("..")) {
            if (resultPath.length() > 0) {
                resultPath.deleteCharAt(resultPath.length() - 1);
            }
        } else {
            // Otherwise, add the component to the result path
            resultPath.append("/");
            resultPath.append(component);
        }
    }

    // Append the remaining path components from the original path
    for (String component : pathComponents) {
        if (!component.isEmpty()) {
            resultPath.append("/");
            resultPath.append(component);
        }
    }

    // Return the final result path
    return resultPath.toString();
}

